INSERT OR REPLACE INTO stivie_knowledge (id, triggerKeywords, category, questionPattern, solutionText, actionType, actionLabel, helpfulCount, learnedFrom, createdAt, updatedAt) VALUES ('k-01', 'duplicar,pantalla,proyector,duplicidad,segunda pantalla,monitor,clonar,no proyecta,reflejar', 'Pantalla', 'Problemas de duplicación de pantalla o proyector secundario', '¡Hola! Detecté que necesitas duplicar la pantalla hacia un proyector o monitor secundario. He preparado la solución nativa directa de Windows (DisplaySwitch /clone) para que lo resuelvas en 1 clic sin llamar a soporte técnico.', 'display_clone', '🪟 Duplicar Pantalla Ahora (1-Clic Nativo)', 0, 'aprendizaje_maestro', '2026-10-20T20:14:56.995Z', '2026-10-25T02:28:16.108Z');
INSERT OR REPLACE INTO stivie_knowledge (id, triggerKeywords, category, questionPattern, solutionText, actionType, actionLabel, helpfulCount, learnedFrom, createdAt, updatedAt) VALUES ('k-02', 'internet,lento,red,desconectado,wifi,dns,sin red,cable,gateway', 'Red', 'Sin conexión a internet o lentitud de navegación LAN', 'He analizado los parámetros de red. La mayoría de problemas de navegación se solucionan liberando y renovando la caché DNS de Windows y refrescando la dirección IP del adaptador de red.', 'flush_dns', '⚡ Limpiar Caché DNS y Refrescar Red', 0, 'aprendizaje_maestro', '2026-10-20T20:14:56.995Z', '2026-10-20T20:14:56.995Z');
INSERT OR REPLACE INTO stivie_knowledge (id, triggerKeywords, category, questionPattern, solutionText, actionType, actionLabel, helpfulCount, learnedFrom, createdAt, updatedAt) VALUES ('k-03', 'lento,congelado,ram,memoria,traba,bloqueado,disco,rendimiento', 'Rendimiento', 'Equipo extremadamente lento o congelamiento de aplicaciones', 'He revisado el inventario de hardware de tu equipo. Cuando la memoria RAM o procesos en segundo plano se saturan, un reinicio limpio programado restaura el rendimiento al 100%.', 'restart', '🔄 Solicitar Reinicio Limpio de Estación', 0, 'aprendizaje_maestro', '2026-10-20T20:14:56.995Z', '2026-10-20T20:14:56.995Z');
INSERT OR REPLACE INTO stivie_knowledge (id, triggerKeywords, category, questionPattern, solutionText, actionType, actionLabel, helpfulCount, learnedFrom, createdAt, updatedAt) VALUES ('k-04', 'impresora,imprimir,hojas,cola,spooler,no imprime,impresion', 'Impresión', 'La impresora no responde o documentos atascados en cola', 'Se detecta bloqueo en el servicio de cola de impresión (Spooler de Windows). Se enviará una orden de reinicio del servicio de impresión para desbloquear los trabajos pendientes.', 'restart_spooler', '🖨️ Desbloquear Cola de Impresión', 0, 'aprendizaje_maestro', '2026-10-20T20:14:56.995Z', '2026-10-20T20:14:56.995Z');
INSERT OR REPLACE INTO stivie_knowledge (id, triggerKeywords, category, questionPattern, solutionText, actionType, actionLabel, helpfulCount, learnedFrom, createdAt, updatedAt) VALUES ('k-05', 'remoto,asistencia,ayuda,tecnico,entrar,soporte,control', 'Soporte TI', 'Requiero asistencia directa de un técnico de soporte TI', 'He notificado al panel central de TI. Puedes habilitar una sesión de Escritorio Remoto con el botón inferior para que el auditor TI se conecte de inmediato.', 'remote_access', '🖥️ Iniciar Sesión de Acceso Remoto RDP', 0, 'aprendizaje_maestro', '2026-10-20T20:14:56.995Z', '2026-10-23T19:51:09.872Z');
